import pg from "pg";
var { Pool } = pg;
var pool = null;
var getPostgresPool = (configOverride) => {
  if (pool) return pool;
  const connectionString = configOverride?.connectionString || process.env.DATABASE_URL;
  if (!connectionString) {
    throw new Error(
      "[PostgreSQL Client Error]: DATABASE_URL environment variable is not defined and no connection configuration was provided."
    );
  }
  pool = new Pool({
    connectionString,
    ssl: process.env.NODE_ENV === "production" ? { rejectUnauthorized: false } : void 0,
    max: configOverride?.maxConnections || 20,
    idleTimeoutMillis: configOverride?.idleTimeoutMillis || 3e4,
    connectionTimeoutMillis: configOverride?.connectionTimeoutMillis || 5e3
  });
  pool.on("error", (err) => {
    console.error("[PostgreSQL Pool Error]: Unexpected error on idle client", err);
  });
  return pool;
};

